import{_ as r,C as n,o as s,c as i,j as t,a,E as d,a2 as l}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Meet PaperSeek","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/index.md","filePath":"get-started/index.md","lastUpdated":1792570296000}'),c={name:"get-started/index.md"};function p(h,e,u,m,w,g){const o=n("StartOptions");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"meet-paperseek",tabindex:"-1"},[a("Meet PaperSeek "),t("a",{class:"header-anchor",href:"#meet-paperseek","aria-label":'Permalink to "Meet PaperSeek"'},"​")],-1)),e[1]||(e[1]=t("p",null,"PaperSeek is an open-source literature research workspace. Start with a question, discover relevant papers, follow their citation connections, and organize the evidence into a review.",-1)),e[2]||(e[2]=t("p",null,"It combines language models with scholarly data sources. You can inspect the search strategy and progress, open original records, and export a reading list.",-1)),e[3]||(e[3]=t("h2",{id:"choose-your-edition",tabindex:"-1"},[a("Choose your edition "),t("a",{class:"header-anchor",href:"#choose-your-edition","aria-label":'Permalink to "Choose your edition"'},"​")],-1)),e[4]||(e[4]=t("p",null,"Use PaperSeek online, or run the community edition on your own computer or server. Choose the option that fits your work and start your first search.",-1)),d(o),e[5]||(e[5]=l('<h3 id="how-do-the-two-options-compare" tabindex="-1">How do the two options compare? <a class="header-anchor" href="#how-do-the-two-options-compare" aria-label="Permalink to &quot;How do the two options compare?&quot;">​</a></h3><p>Search, results, citation maps, bibliometrics, and reviews work the same way in both; the difference is where your data lives and whose models you use.</p><table tabindex="0"><thead><tr><th></th><th>PaperSeek online</th><th>Community edition</th></tr></thead><tbody><tr><td>Start</td><td>Open <a href="https://paperseek.app/" target="_blank" rel="noreferrer">paperseek.app</a></td><td>Install on your computer or server</td></tr><tr><td>Models</td><td>PaperSeek Service with daily credits, or your own keys</td><td>Your own model services, including local endpoints</td></tr><tr><td>History</td><td>Your signed-in account</td><td>Local database and files</td></tr><tr><td>Account</td><td>Required for saved history and reviews</td><td>Not required</td></tr><tr><td>Model cost</td><td>Free daily credits during the public beta</td><td>Your own provider accounts</td></tr></tbody></table><p>Choose <strong>online</strong> to start researching now without installing anything. Choose <strong>Community</strong> to keep data on your own machine, use local or private model endpoints, or work without an account. You can switch later — the workflow is the same.</p><h2 id="a-complete-research-workflow" tabindex="-1">A complete research workflow <a class="header-anchor" href="#a-complete-research-workflow" aria-label="Permalink to &quot;A complete research workflow&quot;">​</a></h2><ol><li><strong>Describe the question.</strong> Include the subject, relationship, and context that matter.</li><li><strong>Search and refine.</strong> PaperSeek plans and iterates source-specific queries.</li><li><strong>Inspect the papers.</strong> Read abstracts, relevance explanations, metadata, and source links.</li><li><strong>Explore connections.</strong> With OpenAlex citation expansion, look beyond the initial results.</li><li><strong>Develop a review.</strong> Select papers, approve an outline, and draft from their abstract evidence.</li></ol><h2 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h2><p>PaperSeek helps discover and organize literature. It does not guarantee an exhaustive systematic search or replace reading original papers. A relevance score is not a study-quality assessment. The review feature uses available abstracts and metadata, not automatically retrieved full text.</p><p>Your source, model, budget, and optional ranking stages affect coverage, latency, and provider usage.</p><h2 id="where-next" tabindex="-1">Where next? <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next?&quot;">​</a></h2><ul><li><a href="./../guide/">User guides</a>: search, results, bibliometrics, reviews, and workspace setup.</li><li><a href="./../online/">PaperSeek online</a>: accounts, credits, and your own keys.</li><li><a href="./../self-hosting/">Self-hosting</a>: Docker, data, network, and upgrades.</li></ul>',11))])}const b=r(c,[["render",p]]);export{k as __pageData,b as default};
